#!/bin/sh\nset -e\n\n# Helper to run the script with given env vars\nrun_countdown() {\n  END_DATE=$1 CURRENT_DATE=$2 sh ./src/countdown.sh\n}\n\n# Test 1: correct calculation (30 days difference)\nEXPECTED="⏳ Time until apocalypse: 30 days, 00 hours, 00 minutes"\nOUTPUT=$(run_countdown 2026-12-31 2026-12-01)\nif [ "$OUTPUT" = "$EXPECTED" ]; then\n  echo "Test 1 passed"\nelse\n  echo "Test 1 failed: expected '$EXPECTED', got '$OUTPUT'"\n  exit 1\nfi\n\n# Test 2: missing END_DATE should error\nif sh -c 'END_DATE= CURRENT_DATE=2026-12-01 sh ./src/countdown.sh' >/dev/null 2>&1; then\n  echo "Test 2 failed: expected error on missing END_DATE"\n  exit 1\nelse\n  echo "Test 2 passed"\nfi\n\n# Test 3: apocalypse already passed\nEXPECTED="The apocalypse has already arrived."\nOUTPUT=$(run_countdown 2025-01-01 2026-01-01)\nif [ "$OUTPUT" = "$EXPECTED" ]; then\n  echo "Test 3 passed"\nelse\n  echo "Test 3 failed: expected '$EXPECTED', got '$OUTPUT'"\n  exit 1\nfi\n
